export const gateway = {
  async charge(req) {
    return fetch("https://pay.example/charge", { method: "POST", body: JSON.stringify(req) });
  },
};

import { chargeCard } from "../billing/charge";
import { loadCart, markCartPaid } from "./cart";

export async function checkout(cartId) {
  const cart = await loadCart(cartId);
  await chargeCard(cart.customerId, cart.total);
  await markCartPaid(cartId);
}
